package org.apache.commons.math3.distribution;

import org.junit.Test;
import org.junit.Assert;
import org.apache.commons.math3.util.Pair;
import java.util.Arrays;
import java.util.List;

public class AgentBRT_Math_8_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        // Setup a distribution with a simple case
        List<Pair<Integer, Double>> samples = Arrays.asList(
            new Pair<>(1, 0.2),
            new Pair<>(2, 0.5),
            new Pair<>(3, 0.3)
        );
        DiscreteDistribution<Integer> distribution = new DiscreteDistribution<>(samples);

        try {
            // Attempt to sample with a size of 3
            Integer[] result = distribution.sample(3);
            // If no exception is thrown, the test should fail
            Assert.fail("Expected ClassCastException was not thrown.");
        } catch (ClassCastException e) {
            // Expected path: ClassCastException should be thrown
            Assert.assertTrue("ClassCastException was thrown as expected.", true);
        }
    }
}

